import Foundation
import XCTest
@testable import JyotishCore

/// End-to-end oracle generated by scripts/generate_parity_fixtures.py using the
/// unmodified Python source and the same bundled Swiss Ephemeris files.
final class PythonParityTests: XCTestCase {
    private struct Fixture: Decodable { let cases: [Case] }
    private struct Case: Decodable {
        let id: String, timeZone: String, localDate: String
        let utc: Double, latitude: Double, longitude: Double, dashaAt: Double
        let natal: ReferenceNatal
        let mahadashas: [ReferencePeriod], currentDasha: [ReferencePeriod]
        let annual: [ReferenceAnnual]
    }
    private struct ReferenceChart: Decodable {
        let julianDay: Double, ascendant: Double
        let positions: [ReferencePosition]
        let ascendantVargas: [String: Int]
    }
    private struct ReferenceNatal: Decodable {
        let julianDay: Double, ascendant: Double
        let positions: [ReferencePosition]
        let ascendantVargas: [String: Int]
        let special: ReferenceSpecial
        var chart: ReferenceChart { ReferenceChart(julianDay: julianDay, ascendant: ascendant, positions: positions, ascendantVargas: ascendantVargas) }
    }
    private struct ReferencePosition: Decodable {
        let name: String
        let longitude: Double, speed: Double, degree: Double
        let signIndex: Int, retrograde: Bool
        let nakshatra: NakshatraInfo
        let vargas: [String: Int]
    }
    private struct ReferenceSpecial: Decodable {
        let arudhaSign: Int, upapadaSign: Int, darapadaSign: Int
        let bhriguBinduLongitude: Double
        let gulika: ReferenceGulika
    }
    private struct ReferenceGulika: Decodable {
        let longitude: Double?, mandiLongitude: Double?, mandiGhatikas: Double?, periodStart: Double?
        let isDayBirth: Bool?, segmentNumber: Int?, weekdayForLord: Int?
        let error: String?
    }
    private struct ReferencePeriod: Decodable { let lord: String; let start: Double, end: Double }
    private struct ReferenceCandidate: Decodable {
        let role: String, planet: String
        let strengthScore: Double
        let aspectsAscendant: Bool
        let bala: PanchaVargiyaBala
    }
    private struct ReferenceAnnual: Decodable {
        let year: Int, completedYears: Int, munthaSignIndex: Int, arudhaSign: Int
        let returnTime: Double, nextJulianDay: Double, bhriguBinduLongitude: Double
        let isDay: Bool
        let chart: ReferenceChart
        let sahams: [String: Double]
        let gulika: ReferenceGulika
        let mudda: [ReferencePeriod]
        let candidates: [ReferenceCandidate]
        let winnerRole: String?
        let ithasala: [TajikaRelation], isarapha: [TajikaRelation]
        let masa: [ReferenceMasa]
    }
    private struct ReferenceMasa: Decodable {
        let monthNumber: Int, arudhaSign: Int
        let returnTimeMinute: Double, bhriguBinduLongitude: Double
        let chart: ReferenceChart
        let gulika: ReferenceGulika
    }
    private func fixture() throws -> [Case] {
        let path = try XCTUnwrap(Bundle.module.url(forResource: "PythonParity", withExtension: "json"))
        let f = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: path))
        XCTAssertEqual(f.cases.count, 4)
        return f.cases
    }
    private func assertAngle(_ actual: Double, _ expected: Double, _ label: String,
                             file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertEqual(Astro.signedDifference(actual - expected), 0, accuracy: 1e-7, label, file: file, line: line)
    }
    private func assertChart(_ actual: Chart, _ expected: ReferenceChart, _ label: String) throws {
        XCTAssertEqual(actual.julianDay, expected.julianDay, accuracy: 1e-9, label)
        assertAngle(actual.ascendantLongitude, expected.ascendant, label + "/ascendant")
        XCTAssertEqual(actual.positions.count, 9, label)
        for p in expected.positions {
            let a = try XCTUnwrap(actual.positions[p.name], label + "/" + p.name)
            assertAngle(a.longitude, p.longitude, label + "/" + p.name)
            // The macOS runner differs from Linux-generated references by up
            // to 2.21884e-8 deg/day in Swiss finite-difference speed corrections.
            // This comparison budget is 0.00018 arcsec/day; positions retain
            // 1e-7 degree and categorical/sign/retrograde checks stay exact.
            // See docs/NUMERICAL_PARITY.md for the recorded CI measurements.
            XCTAssertEqual(a.speed, p.speed, accuracy: 5e-8, label + "/speed/" + p.name)
            XCTAssertEqual(a.degree, p.degree, accuracy: 1e-7, label)
            XCTAssertEqual(a.signIndex, p.signIndex, label)
            XCTAssertEqual(a.isRetrograde, p.retrograde, label)
            let nak = try Nakshatra.at(longitude: a.longitude)
            XCTAssertEqual(nak.name, p.nakshatra.name, label)
            XCTAssertEqual(nak.index, p.nakshatra.index, label)
            XCTAssertEqual(nak.pada, p.nakshatra.pada, label)
            XCTAssertEqual(nak.lord, p.nakshatra.lord, label)
            XCTAssertEqual(nak.fractionElapsed, p.nakshatra.fractionElapsed, accuracy: 1e-8, label)
            for v in Varga.allCases {
                XCTAssertEqual(try v.signIndex(longitude: a.longitude), p.vargas[String(v.rawValue)], label + "/" + v.label)
            }
        }
        for v in Varga.allCases {
            XCTAssertEqual(try v.ascendantSign(chart: actual), expected.ascendantVargas[String(v.rawValue)], label + "/asc/" + v.label)
        }
    }
    private func assertGulika(_ actual: GulikaResult?, _ expected: ReferenceGulika, _ label: String) throws {
        if expected.error != nil { XCTAssertNil(actual, label); return }
        let a = try XCTUnwrap(actual, label)
        assertAngle(a.longitude, try XCTUnwrap(expected.longitude), label + "/Gulika")
        assertAngle(try XCTUnwrap(a.mandiLongitude), try XCTUnwrap(expected.mandiLongitude), label + "/Mandi")
        XCTAssertEqual(a.mandiGhatikas, expected.mandiGhatikas, label)
        XCTAssertEqual(a.isDayBirth, expected.isDayBirth, label)
        XCTAssertEqual(a.segmentNumber, expected.segmentNumber, label)
        XCTAssertEqual(a.weekdayForLord, expected.weekdayForLord, label)
        XCTAssertEqual(a.periodStart.timeIntervalSince1970, try XCTUnwrap(expected.periodStart), accuracy: 1e-4, label)
    }
    private func assertPeriods(_ actual: [DashaPeriod], _ expected: [ReferencePeriod], _ label: String) {
        XCTAssertEqual(actual.count, expected.count, label)
        for (a, e) in zip(actual, expected) {
            XCTAssertEqual(a.lord, e.lord, label)
            // The end-to-end input Moon comes from platform C floating-point
            // calculations. Its last bits are amplified over multi-year dashas.
            // macOS/Linux observed ~30µs; keep a 100µs comparison allowance.
            // Pure dasha arithmetic/coverage and lord selection stay exact.
            XCTAssertEqual(a.start.timeIntervalSince1970, e.start, accuracy: 0.0001, label)
            XCTAssertEqual(a.end.timeIntervalSince1970, e.end, accuracy: 0.0001, label)
        }
    }
    private func assertRelations(_ actual: [TajikaRelation], _ expected: [TajikaRelation], _ label: String) {
        XCTAssertEqual(actual.map(\.id), expected.map(\.id), label)
        for (a, e) in zip(actual, expected) {
            XCTAssertEqual(a.aspect, e.aspect, label)
            XCTAssertEqual(a.faster, e.faster, label)
            XCTAssertEqual(a.slower, e.slower, label)
            XCTAssertEqual(a.withinOrb, e.withinOrb, label)
            XCTAssertEqual(a.isApplying, e.isApplying, label)
            XCTAssertEqual(a.isSeparating, e.isSeparating, label)
            XCTAssertEqual(a.isExact, e.isExact, label)
            XCTAssertEqual(a.orbDifference, e.orbDifference, accuracy: 1e-7, label)
            XCTAssertEqual(a.combinedOrb, e.combinedOrb, accuracy: 1e-12, label)
            // Difference of two velocities: propagate twice the 5e-8 budget.
            XCTAssertEqual(a.relativeSpeed, e.relativeSpeed, accuracy: 1e-7, label)
        }
    }

    func testNatalAllVargasSpecialPointsAndFiveDashaLevelsAgainstPython() throws {
        XCTAssertEqual(Ephemeris.version, "2.10.03")
        for c in try fixture() {
            let birth = Date(timeIntervalSince1970: c.utc)
            let n = try Natal.compute(date: birth, localDate: c.localDate, latitude: c.latitude, longitude: c.longitude)
            try assertChart(n.chart, c.natal.chart, c.id + "/natal")
            let e = c.natal.special, a = n.specialPoints
            XCTAssertEqual(a.arudhaSign, e.arudhaSign, c.id)
            XCTAssertEqual(a.upapadaSign, e.upapadaSign, c.id)
            XCTAssertEqual(a.darapadaSign, e.darapadaSign, c.id)
            assertAngle(a.bhriguBinduLongitude, e.bhriguBinduLongitude, c.id)
            try assertGulika(a.gulika, e.gulika, c.id + "/natal")
            let moon = try XCTUnwrap(n.chart.positions["Mjesec"]).longitude
            assertPeriods(try Dasha.mahadashas(moonLongitude: moon, birthDate: birth), c.mahadashas, c.id + "/maha")
            assertPeriods(try Dasha.currentFiveLevels(moonLongitude: moon, birthDate: birth, at: Date(timeIntervalSince1970: c.dashaAt)), c.currentDasha, c.id + "/five")
        }
    }

    func testAnnualAllSahamsLordComponentsMuddaAndAspectsAgainstPython() throws {
        var annualCount = 0
        for c in try fixture() {
            for e in c.annual {
                let label = c.id + "/" + String(e.year)
                let zone = try XCTUnwrap(TimeZone(identifier: c.timeZone))
                let a = try Annual.calculate(birthDate: Date(timeIntervalSince1970: c.utc), latitude: c.latitude,
                                             longitude: c.longitude, year: e.year, birthTimeZone: zone)
                try assertChart(a.chart, e.chart, label)
                XCTAssertEqual(a.returnDate.timeIntervalSince1970, e.returnTime, accuracy: 0.1, label)
                XCTAssertEqual(Ephemeris.julianDay(date: a.nextReturnDate), e.nextJulianDay, accuracy: 1e-9, label)
                XCTAssertEqual(a.completedYears, e.completedYears, label)
                XCTAssertEqual(a.munthaSignIndex, e.munthaSignIndex, label)
                XCTAssertEqual(a.isDay, e.isDay, label)
                XCTAssertEqual(a.sahams.count, 20, label)
                for (name, longitude) in e.sahams { assertAngle(try XCTUnwrap(a.sahams[name]), longitude, label + "/" + name) }
                XCTAssertEqual(a.arudhaSign, e.arudhaSign, label)
                assertAngle(a.bhriguBinduLongitude, e.bhriguBinduLongitude, label + "/BP")
                try assertGulika(a.gulika, e.gulika, label)
                assertPeriods(a.muddaDasha, e.mudda, label + "/mudda")
                XCTAssertEqual(a.varsheshwara.candidates.count, 5, label)
                for (ac, ec) in zip(a.varsheshwara.candidates, e.candidates) {
                    XCTAssertEqual(ac.role, ec.role, label)
                    XCTAssertEqual(ac.planet, ec.planet, label)
                    XCTAssertEqual(ac.strengthScore, ec.strengthScore, accuracy: 1e-12, label)
                    XCTAssertEqual(ac.aspectsAscendant, ec.aspectsAscendant, label)
                    XCTAssertEqual(ac.bala.kshetra, ec.bala.kshetra, accuracy: 1e-10, label)
                    XCTAssertEqual(ac.bala.uchcha, ec.bala.uchcha, accuracy: 1e-10, label)
                    XCTAssertEqual(ac.bala.hadda, ec.bala.hadda, accuracy: 1e-10, label)
                    XCTAssertEqual(ac.bala.drekkana, ec.bala.drekkana, accuracy: 1e-10, label)
                    XCTAssertEqual(ac.bala.navamsa, ec.bala.navamsa, accuracy: 1e-10, label)
                }
                XCTAssertEqual(a.varsheshwara.winner?.role, e.winnerRole, label)
                assertRelations(a.ithasala, e.ithasala, label + "/Ithasala")
                assertRelations(a.isarapha, e.isarapha, label + "/Isarapha")
                annualCount += 1
            }
        }
        XCTAssertEqual(annualCount, 5)
    }

    func testAllSixtyMonthlyChartsAgainstPythonWithDocumentedTimePrecision() throws {
        var count = 0
        for c in try fixture() {
            let birth = Date(timeIntervalSince1970: c.utc)
            let natal = try Ephemeris.chart(date: birth, latitude: c.latitude, longitude: c.longitude)
            let sun = try XCTUnwrap(natal.positions["Sunce"]).longitude
            for annual in c.annual {
                let months = try Annual.masa(natalSunLongitude: sun, annualJulianDay: annual.chart.julianDay,
                                             latitude: c.latitude, longitude: c.longitude)
                XCTAssertEqual(months.count, 12)
                for (a, e) in zip(months, annual.masa) {
                    let label = c.id + "/masa/" + String(annual.year) + "/" + String(e.monthNumber)
                    XCTAssertEqual(a.monthNumber, e.monthNumber, label)
                    try assertChart(a.chart, e.chart, label)
                    // Original Python model drops seconds; native retains the
                    // actual solver instant while preserving chart positions.
                    XCTAssertEqual(floor(a.returnDate.timeIntervalSince1970 / 60) * 60, e.returnTimeMinute, accuracy: 0.001, label)
                    XCTAssertEqual(a.arudhaSign, e.arudhaSign, label)
                    assertAngle(a.bhriguBinduLongitude, e.bhriguBinduLongitude, label)
                    try assertGulika(a.gulika, e.gulika, label)
                    count += 1
                }
            }
        }
        XCTAssertEqual(count, 60)
    }
}
